findings.codeql_raw_query:
/**
 * @name SSRF in aiohappyeyeballs
 * @description User input flowing to network connection sinks
 * @kind problem
 * @problem.severity warning
 * @id py/ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SsrfConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for socket.connect calls
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("socket").getMember("socket").getACall().getReturn().getMember("connect").getACall() and
      sink = call.getArg(0)
    ) or
    // Check for asyncio.open_connection
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("asyncio").getMember("open_connection").getACall() and
      sink = call.getArg(0)
    )
  }
}

module SsrfFlow = TaintTracking::Global<SsrfConfig>;

from DataFlow::Node source, DataFlow::Node sink
where SsrfFlow::flow(source, sink)
select sink, "SSRF vulnerability: user input flows to network connection"
